                return {"target": -1, "stop": None, "take": None}
        else:
            if pos == 1 and current_30.high > current_30_upper:
                return {"target": 0, "stop": None, "take": None}
            elif pos == -1 and current_30.low < current_30_lower:
                return {"target": 0, "stop": None, "take": None}

    # Check if the position should be closed
